#include<limits.h>
/*@
	assigns \nothing;
	ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();

#define N 10000
#define fun xor

#include <assert.h>

/*@
	@axiomatic XorFold {
		logic integer xor_fold(int *a, integer lo, integer hi);
		axiom xor_fold_empty: \forall int *a, integer lo;
		xor_fold(a, lo, lo) == 0;
		axiom xor_fold_step: \forall int *a, integer lo, integer hi;
		lo < hi ==> xor_fold(a, lo, hi) == xor_fold(a, lo, hi-1) ^ a[hi-1];
		axiom xor_fold_split: \forall int *a, integer lo, mid, hi;
		lo <= mid <= hi ==>
		xor_fold(a, lo, hi) == xor_fold(a, lo, mid) ^ xor_fold(a, mid, hi);
	}
*/

/*@
	requires \valid(x + (0 .. N-1));
	assigns \nothing;
	ensures \result == xor_fold(x, 0, N);
*/
int xor (int x[N])
{
	int i;
	long long res;
	res = x[0];
	for (int i = 1; i < N; i++) {
		/*@
		loop invariant 1 <= i <= N;
		loop invariant res == xor_fold(x, 0, i);
		loop assigns i, res;
		loop variant N - i;
		*/
	}
	return res;
}

int main ()
{
	int x[N];
	int temp;
	int ret;
	int ret2;
	int ret5;
	for (int i = 0; i < N; i++) {
		x[i] = unknown();
	}
	/*@
	loop invariant 0 <= i <= N;
	loop invariant \forall integer k; 0 <= k < i ==> x[k] == unknown();
	loop invariant x[0 .. N-1] == unknown() .. unknown();
	loop assigns i, x[0 .. N-1];
	loop variant N - i;
	*/
	ret = fun(x);
	temp=x[0];x[0] = x[1]; x[1] = temp;
	ret2 = fun(x);
	temp=x[0];
	for(int i =0 ; i<N-1; i++){
		/*@
		loop invariant 0 <= i < N;
		loop invariant \forall integer k; 0 <= k < i ==> x[k] == \old(x[k+1]);
		loop invariant x[N-1] == \old(x[0]);
		loop invariant \forall integer k; 0 <= k < N ==>
		x[k] == \old(x[k]) ||
		(\exists integer j; 0 <= j < N && x[k] == \old(x[j]));
		loop invariant xor_fold(x, 0, N) == xor_fold(\old(x), 0, N);
		loop assigns i, x[0 .. N-1];
		loop variant N - 1 - i;
		*/
	}
	ret5 = fun(x);
	//@ assert !(ret != ret2 || ret !=ret5);
	return 1;
}
